    /// Computes S(k) = sum_{x=0}^k (-1)^x * x
    /// 
    /// Defined by:
    ///    S(0) = 0
    ///    S(k) = k/2          if k is even and k > 0
    ///    S(k) = -((k+1)/2)   if k is odd
    ///
